namespace Novior.MentorAgent.Models;

/// <summary>
/// Optional override for the A2A Agent Card generated by MentorAgent when
/// <c>options.A2AServerEnabled = true</c>.
///
/// If not set, the card is built automatically from <c>AppName</c>, <c>AppDescription</c>,
/// and the discovered <c>[MentorAction]</c> methods.
///
/// Usage:
/// <code>
/// options.AgentCard = new AgentCardInfo {
///     Version = "2.0.0",
///     IconUrl = "https://myapp.com/icon.png",
///     Provider = "Acme Corp",
///     DocumentationUrl = "https://docs.myapp.com/agent"
/// };
/// </code>
/// </summary>
public sealed class AgentCardInfo
{
    /// <summary>Agent version string. Default: "1.0.0"</summary>
    public string Version { get; set; } = "1.0.0";

    /// <summary>URL to the agent's icon image.</summary>
    public string? IconUrl { get; set; }

    /// <summary>Provider / organization name.</summary>
    public string? Provider { get; set; }

    /// <summary>URL to the agent's documentation.</summary>
    public string? DocumentationUrl { get; set; }

    /// <summary>
    /// Reserved — <b>not published today</b>.
    ///
    /// <para>
    /// The A2A card has no top-level tags field: the spec attaches tags to individual
    /// <c>AgentSkill</c> entries, and MentorAgent does not synthesise skills it cannot describe
    /// truthfully. Setting this has no effect on the served card. It is kept because the intent —
    /// capability hints for discovery — is right, and it will map once skills are published.
    /// </para>
    /// </summary>
    public string[]? Tags { get; set; }
}
